/**
 * Meta-prompt template for AI recommendation generation.
 *
 * This template guides the AI to analyze a task and recommend
 * the appropriate next action.
 *
 * Workflow labels (1):
 * - bug: Investigating unexpected behavior
 */

import { resolvePromptUi } from '../prompt-formatters.js';
import { extractPrincipleZeroTest } from './autopilot-manual.js';
import { routerFragments, applyRouterCapabilities } from '../stage-router.js';

/**
 * Generate the meta-prompt for AI task recommendation.
 *
 * @param {Object} params - Template parameters
 * @param {string} params.issueContext - Formatted issue context string
 * @param {string} params.identifier - Issue identifier (e.g., "LIN-123")
 * @param {boolean} params.hasSubtasks - Whether the issue has subtasks
 * @param {number} params.subtaskCount - Number of subtasks
 * @param {number} params.completedCount - Number of completed subtasks
 * @param {number} params.inProgressCount - Number of in-progress subtasks
 * @param {number} params.remainingCount - Number of remaining (non-completed) subtasks
 * @param {boolean} params.hasComments - Whether the issue has comments
 * @param {number} params.commentCount - Number of comments
 * @param {string} params.aiHints - Formatted AI hints for action types
 * @param {string} [params.completionSignals] - Formatted completion signals for assessment
 * @param {string} [params.focusedSubtaskId] - Identifier of pre-selected focused subtask (two-tier mode)
 * @param {Object} [params.featureFlags] - Feature toggle flags
 * @param {boolean} [params.featureFlags.linearMcp=true] - Include Linear references in workflow steps
 * @param {boolean} [params.featureFlags.codeReview=false] - Include code review instructions
 * @param {boolean} [params.featureFlags.codeReviewSelf=true] - Self-review before committing
 * @param {boolean} [params.featureFlags.codeReviewCicd=false] - CI/CD check after pushing
 * @param {boolean} [params.featureFlags.codeReviewPr=false] - PR review before completing
 * @returns {string} Complete meta-prompt for the AI
 */
// Clause (10) of the Implementation-prompts quality rule below adds an
// acceptance-witness discipline for tests, extending the bug/investigate template's
// witness-validation rule (canonical source: lib/prompt-template-defs.js:127 — do not
// restate that wording here).
export function buildMetaPromptTemplate({
  issueContext,
  identifier,
  hasSubtasks,
  subtaskCount,
  completedCount,
  inProgressCount,
  remainingCount,
  hasComments,
  commentCount,
  aiHints,
  actionVocabulary,
  completionSignals,
  focusedSubtaskId,
  frontierFacts = null,
  isTerminal = false,
  hasOpenChildren = false,
  featureFlags = {},
  providerUi = null,
  routingOnly = false
}) {
  // LIN-2977: compose from the manual's own extractor so this can't drift from it the
  // way the old hand-copied literal did (LIN-2973 pattern, closed here on the meta path).
  const principleZeroTest = extractPrincipleZeroTest();
  const principleZeroTestFlat = principleZeroTest
    ? principleZeroTest.replace(/^>\s?/gm, '').replace(/\s+/g, ' ').trim()
    : 'Does this genuinely require the human, right now — or is it just something the human might like to see?';
  // Capability-aware (LIN-177 S5). Provider capability is the hard floor; the
  // linearMcp user flag is a soft preference within a writable provider. For Linear
  // with the flag on, `caps` is the Linear floor and every transform below is a
  // no-op, so the meta-prompt is byte-identical. The tracker name and the
  // " in {tracker}" suffix are renamed/stripped on the assembled string at the end.
  // Routing only (LIN-3292): the call picks the action and gives its reasoning; code
  // assembles the stage's rules and the brief writer writes the prompt.
  const W = (text) => routingOnly ? '' : text;
  const caps = resolvePromptUi(featureFlags, providerUi);
  const useLinear = caps.includeTracker;
  const canWrite = caps.write;
  const useCodeReview = featureFlags.codeReview === true;
  const useSelfReview = useCodeReview && featureFlags.codeReviewSelf !== false;
  const useCicdCheck = useCodeReview && featureFlags.codeReviewCicd === true;
  const usePrReview = useCodeReview && featureFlags.codeReviewPr === true;

  // The routing half lives in lib/stage-router.js (LIN-3304): the meta template
  // composes the SAME fragments, so the full path is byte-identical and routing-only
  // is no longer a subtractive mask. routingOnly blanks the writing blocks below.
  const R = routerFragments({ issueContext, identifier, hasSubtasks, subtaskCount, completedCount, inProgressCount, remainingCount, hasComments, commentCount, aiHints, actionVocabulary, completionSignals, focusedSubtaskId, frontierFacts, isTerminal, hasOpenChildren });
  const metaPrompt = `${R.role}${W(' Generate a tailored prompt they can use with Claude Code.')}${R.context}${W(`## Grounding Rule (applies to every prompt you generate)

The generated prompt must only contain information explicitly present in the Task Context above. Do not infer file paths, schemas, status codes, error contracts, UI specifics (sizes, colors, positions), workflow states, downstream components, framework names, or acceptance criteria from the task title or general knowledge.

When a quality rule below asks for a detail the ticket does not contain, instruct the consumer to determine it from the codebase (e.g., "identify the response schema from existing endpoints in this codebase", "find dependents of this shared system before changing it") rather than supplying a value yourself. Research, design, and verification are the consumer's responsibility — your job is to route to the right action and faithfully restate the ticket.

## Scale To The Task (output size)

Match the size of the generated prompt to the task's ACTUAL scale — not to the size of this template, and not to the length of the discussion you were handed. The structure below is a ceiling, not a quota.

- **Small / single-surface / obvious task** (a typo, a constant or config change, a one-file validation, or a task whose plan already fits one focused session): generate a SHORT prompt. A few focused steps plus a one-line scope note is a complete, valid result. Do NOT pad it out with the full battery of framing, completeness, cross-cutting, and history-reading sub-checks — naming the one file and the one change is enough. A short prompt for a small task is correct, not lazy.
- **Multi-surface / cross-cutting / migration / genuinely uncertain task:** use the full structure — that depth is earned.
- **Do NOT infer "small" from a terse description.** A one-line ticket can be large. Renaming, moving, refactoring, or migrating a name "everywhere" / "across the codebase", changing a shared identifier or a widely-used symbol, or anything that fans out to many call sites is MULTI-SURFACE even when described in a single sentence. Size to the fan-out you can actually verify, not to the ticket's brevity — when a task is tersely worded and you cannot confirm it is single-surface, keep the full structure rather than shrinking.
- When unsure, size to the surfaces the task actually touches, not to the template. The quality rules below tell you what a prompt MAY contain; this rule governs how much of it a given task NEEDS.

`)}${R.decisionIntro}${W(`Keep the generated prompt inside the single action you recommended: its steps produce that action's deliverable, and its final step names the follow-up action. The handoff is a recommendation the system acts on later — each action gets its own prompt, generated fresh when it starts.

`)}${R.decisionRest}${W(`## Prompt Structure
Generate a prompt following this structure. The prompt is an INSTRUCTION that references the task, not a copy of it — do NOT restate the task's description or comment thread (see the Context section below for what to include instead).

\`\`\`
# [Action verb] ${identifier}: [Task title]

## Workflow
${!canWrite
    ? `1. **Fetch details**: Get full issue details for ${identifier}
2. [Action-specific steps]
3. **Summarize**: Present findings to the user — this tracker is read-only, so do NOT instruct status changes or comment/label writes.`
    : useLinear
    ? `1. **Start**: Set ${identifier} status to "In Progress" in Linear (if not already)
2. **Fetch details**: Get full issue details for ${identifier} in Linear
3. [Action-specific steps]
4. **Update Linear**: [How to update Linear when done - add comment, change status/labels, etc.]

Always include the "Start" step to ensure work visibility.`
    : `1. [Action-specific steps]
2. **Update Linear**: [How to update Linear when done - add comment, change status/labels, etc.]`}${useSelfReview ? `

## Self-Review
Before committing, review your changes:
- Verify correctness against task requirements
- Check for security vulnerabilities
- Ensure test coverage for new/changed behavior
- Confirm code style matches the codebase` : ''}${useCicdCheck ? `

## CI/CD Check
After pushing changes:
1. Check CI/CD pipeline status. If the repo has no CI configured, say so explicitly and run the local-suite substitute (PR branch vs base, diffing failure names) instead of waiting on a check that will never appear.
2. Fix any failures before proceeding
3. Do not mark the task as Done until all checks pass (or, with no CI, until the substitute is clean)` : ''}${usePrReview ? `

## PR Review
After creating the pull request:
1. Check for review comments and requested changes
2. Address all feedback
3. Only mark the task as Done after approval and merge` : ''}

## Context
Reference the task rather than restating it. Do NOT copy ${identifier}'s description or comment thread into the prompt — the consumer reads the live task (its brief, or Linear) directly, so a baked-in copy only bloats the prompt and risks going stale. Include only: (a) the lightweight relational pointers that orient the work — project, parent, siblings — as one line each; and (b) any task-specific fact the consumer genuinely needs to act on that is NOT already obvious from the ticket, and only when it is present in the Task Context above.

## Goal
[1–2 short paragraphs: what the work is for, what good looks like, and why]

## Process
[Structured guidance specific to the action type — restrict content to information explicitly present in the Task Context above. If the action type needs a detail the ticket lacks (file paths, schemas, error contracts, downstream components, etc.), instruct the consumer to determine it from the codebase rather than supplying a value.]
\`\`\`

### Quality rules for generated prompts

- **Blocked prompts** must front-load a status check on blocking dependencies — if the blocker is already resolved, skip the full analysis and recommend the next action; if not, clear it when it is the agent's to clear. They must also gate the blocker analysis on Principle 0 and name the cost of doing nothing, citing the manual's **"The human's edge, and how to hand back"** section by name and \`GET /api/proxy/autopilot/manual\` as the way to read it, rather than restating the rubric. The generated prompt must also carry the one-sentence Principle 0 test itself, verbatim, alongside that pointer — a bare pointer with no test sentence strands the consumer with a gate it cannot apply: "${principleZeroTestFlat}"
- **Triage prompts** must check project placement alongside labels, priority, and state — instruct the agent to confirm the task is in the correct project, and when it is unassigned or mis-filed, to list the workspace's projects, pick the right one for the task's scope, and move/assign it directly. Triage is not done while a task sits in the wrong project. Triage prompts must name the priority write field explicitly — any priority change is authorized via the provider-neutral \`priorityLevel\` field (ascending, 4 = highest), matching the close-out rule's precedent below. Triage prompts must also preserve scope: instruct the agent that triage may change only labels, priority, state, and project — it must not rewrite the task's description or otherwise change its scope, and must not create follow-up tasks or subtasks; findings stay observations, never new work items (scope changes belong to the scoping/plan/breakdown steps).
- **Bug prompts** must include a class check once the root cause is in hand — widen the model, don't patch the witness: instruct the agent to ask whether the same pattern produces siblings elsewhere (search for the pattern itself — the failure mode, a shared helper, a parallel code path — not only the cited symptom). If a class exists, the proposed fix is at the shared cause and reaches every instance found, refactoring where that makes the code simpler. A genuinely isolated issue is a valid answer and must be stated explicitly. They must also require a cause-validation gate before any fix is proposed or handed off: name the single decisive experiment that disambiguates the leading hypothesis from its rivals and run it — evidence the cause is confirmed, not merely plausible, is required, and an investigation that proposes a fix while stating the decisive experiment was not run is NOT done (a genuinely confirmed cause is valid and must be stated explicitly). They must require validating the acceptance witness before optimizing against it: confirm the signal called "fixed" actually tracks the real outcome — a witness that can read green while the outcome is wrong (or red while it is right) must be validated or replaced first. And they must search wider than nearby code: prior investigations or runs of the same subsystem and prior diverging episodes (seed from both the technical lead and the meta-pattern, "this class of bug, last time the decisive experiment was X"), not only related fixes.
- **Research prompts** must end with a Surface Assessment gated on necessity, not availability: the question is not "would a refactor make this land better?" (on most code something could be cleaner) but "is the feature's shape demanding a structural change?" — implementing cleanly would mean fighting the current structure. A "refactor required" verdict must pass two evidence tests, each answered by citing lines: the **cause-or-consumer test** (show the refactor removes the confirmed cause of this task's problem, or cite the line in this task's implementation that calls the new seam — neither means speculation, which belongs with its future consumer) and the **who-pays test** (every consumer the refactor touches is either a beneficiary — simpler, corrected, or unchanged — or a bystander paying a named tax; an unjustified bystander tax means scope it down; a small named tax buying a large simplification must be argued explicitly). Size is not a rejection criterion — a demanded refactor that does not fit the session is sequenced, not shrunk. Format: "Surface Assessment: [lands cleanly] / [refactor required: describe the scoped change — reason: the cause it removes, or where this task calls it] / [improvement noticed, not required: land inline/scoped — no separate subtask]". The answer must be explicit — not implied — so the plan step can act on it. Research prompts must also search wider than nearby code — prior investigations or runs of the same subsystem and prior diverging episodes (seed from both the technical lead and the meta-pattern, "this class of problem, last time the decisive experiment was X"), not only related fixes — and must pin the measurement: if the work will be judged by a metric or signal, confirm it actually tracks the real outcome before optimizing against it; a measurement that can read green while the outcome is wrong (or red while it is right) must be validated or replaced first (a measurement that genuinely tracks the outcome is a valid answer and must be stated explicitly). Research prompts must also require an explicit Audit the Layers pass before recommending: enumerate every layer the change touches — every part, seam, or module it must stay consistent with — searching for the concept (what a caller or user observes), not only the symbol the ticket cites, since the same behaviour is often represented under a different name, in a parallel code path, split across server and client, mirrored in a sibling provider/feature, or restated in a published contract. For each layer, instruct the consumer to brief how it is done here today (its patterns, conventions, and normalisations, and what a change must keep consistent) AND to cite a source for each claim — a file:line, a doc path, or a commit — so the brief is verified, not assumed; an uncited claim is a guess. Completion is measured by coverage, not speed — being exhaustive costs the same human attention. As part of each layer's brief, enumerate what the change must hold true against in the existing system — what it must reuse rather than duplicate, stay consistent with across sibling surfaces, keep in sync across sources of truth, preserve behaviourally, and recover from on failure — citing the specific existing thing for each and how the approach honours it. These axes are seed examples, not a fixed checklist (the decisive axis may be concurrency, auth scoping, cache invalidation, rate limits, …); the consumer derives the axes the task actually has, and the target is completeness of reasoning, not a longer list. Research prompts must then include an adversarial self-review pass that CLOSES the layer set — instruct the agent to attack its own audit: what existing structure, sibling surface, sync obligation, failure path, or prior behaviour did it not check, and what did it assert without verifying; it must state the layer set as complete and back it by showing the search that would have surfaced a missed sibling and what it returned, resolving or recording what that turns up before recommending. Research prompts must also require naming the classes the task touches (LIN-1871): for each class — every call site, every lane, every consumer, every shape — name it, say how it was bounded (reasoning: the state machine, the callers, what has landed since the grounding sha, or a grep where a grep is the honest tool — a reproducible query is one way to bound a class, not the only way), and list every member found; a class that cannot be bound is a first-class answer, named as such with why (a destination that does not exist yet in the source tree, or a population that is production data rather than source); record the class, its bound, and its members in the description, since the plan step works from this list and adds a class of its own only if it can say why research missed it. And the Surface Assessment must treat introducing a second representation of something already modelled (a parallel type/table/state/source of truth for existing data) as a "refactor required" signal — reuse or extend the existing model — not a clean landing. All of this applies when the change touches shared structure, multiple surfaces, or already-modelled data; a genuinely small or single-surface change (a typo, a constant, a one-file edit) records the file and the fix, skips the layer audit and adversarial passes, and does not pay the obligation tax. When this task carries attachments, research prompts must also require perceiving EVERY one of them (images actually viewed) before any grounding claim, listing each by title and id rather than referring collectively to "the attachments", with a hard stop on any it cannot perceive: no findings on a partial read — comment naming it and why, and recommend \`blocked\`.
- **Scoping, design, spike, context and look-into prompts** brief the stage's purpose plainly, and each says so when the ticket is aimed at a symptom: scoping reads the code first and decides what is in and out (this problem's cause is never out), flagging only product or intent questions; design starts from the problem and its cause, weighs the genuinely viable shapes, recommends one and says what would change its mind; spike names the one question that decides the rest and what would mean yes or no, proves it against real dependencies within one focused session, and reports the verdict first, leaving the code visible but not landed; context tells someone arriving cold where the ticket really stands (done and how it is known, left, overturned) and what should happen next; look-into explains the ticket to a person and changes nothing.
- **Plan prompts** must include a cross-cutting concerns check: after listing changes, ask whether any requirements share the same code path, state, or interface — and if so, document the expected interaction explicitly. Plan prompts for tasks touching high-churn files must include a history-reading step — high-churn means the same file has 3+ commits in recent history; the plan should document what those changes were protecting against. If a Surface Assessment in prior research comments declares "refactor required" and names the cause it removes or its in-task consumer, the plan prompt must encode it as a separate blocking subtask using the assessment's description directly — do not absorb the refactor into implementation steps, as that loses the sequencing guarantee; a refactor that removes no cause here and has no consumer in this task, or one that taxes bystander consumers, must not become a subtask — the plan folds it inline, scopes it down, or records it as a note. **Plan prompts must also contain a Strategy Framing block placed BEFORE the Scope Assessment / session-fit step.** The Strategy Framing block must: (a) instruct the consumer to score viable strategies on *cost-of-doing* (current-ticket session size, blast radius, risk to high-churn files) vs *cost-of-not-doing* (named contract gap left unsolved, plus the workaround tax — dialect-island / per-runtime branch / duplicated abstraction — paid on every future change); (b) when a cheaper strategy routes around a tracked contract gap, instruct the consumer to NAME that gap explicitly (ticket identifier or "none identified") — a bare description is not enough; (c) default to closing the gap: routing around this task's cause needs a reason it cannot be fixed here — a ticket identifier records the trade-off, never pays for it. Ordering is non-negotiable: Strategy Framing → Scope Assessment → session-fit answer. Reversing it produces post-hoc justification of the cheap default. **Plan prompts must also include a completeness check on the surface list:** instruct the consumer to confirm the list is complete (not just correct) by searching for the concept or behavior itself — which is often implemented in more than one place, under a different name, in a parallel code path, or split across server and client — rather than only the symbol the ticket cites, since a clean search for the cited symbol is not proof of completeness; every instance found is then marked in- or out-of-scope (a genuinely single-surface result is valid — the goal is to make scope a decision, not an accident). **Plan prompts must also require naming the class and how it was bounded, working from research's classes (LIN-1871, revising LIN-1873)** — where research named the classes this task touches, the plan must map every member research found to in- or out-of-scope and add a class of its own only if it can say why research missed it; a plan is sent back for a missing class, never for a missing member inside a class already correctly bounded. Where the plan claims coverage of a CLASS for the first time — every call site, every lane, every consumer, every shape — it must name the class and say how it was bounded: reasoning (the state machine, the callers, what has landed since the grounding sha) or a **reproducible query whose output IS the enumeration** — an \`rg\`/\`grep\` pattern, an AST query, or a test that fails on an unhandled member — which is one way to bound a class and the strongest one where it applies, with its output pasted and the commit sha it was run at recorded, so the reviewer re-runs or re-derives it instead of rediscovering members one at a time. The prompt must equally state that some classes have no sweep and that saying so is a first-class answer, naming the two recurring shapes — the *destinations* of new or moved code, which cannot be swept from code that does not exist yet, and classes whose population is production data rather than source, needing a corpus query rather than a repo query — and must require the consumer to name which shape applies and what bounded the class instead — the test for any third shape being that the members are not in the current source tree at all, so a class that is merely awkward to grep is a harder query rather than an absent one. It must also require the class, its bound, its output (if a query) and its sha to be recorded in the issue description alongside the plan, where plan-review looks for them. It must warn against manufacturing a query, a script, or a checklist to fill the slot — the rule asks for reasoning shown, not a form filled: an honest "no sweep, here is why" is better than a bound that looks authoritative and is quietly incomplete, and a bound whose output does not match what the plan handled is a useful result to report rather than something to trim until it agrees. **Plan prompts must also require the plan to state what it adds beyond the research and cite the rest.** State what it adds beyond the research — the design, the steps, the tests, the scope decisions, and any disagreement with the research and why — and cite the research findings it relies on instead of restating them: cite by comment (author/heading or id), file:line, or sha, so a reader can resolve the citation without the plan paraphrasing it. If there is no prior research, the plan stands alone — that is valid, and there are no citations to manufacture; never restate a finding to "make the plan self-contained". If the plan disagrees with a finding or finds it stale, say so explicitly with the evidence — that is an addition, not a restatement. The in/out-of-scope verdict for each member stays the plan's own decision; the citation covers the member list, not the verdict. When this task carries attachments, plan prompts must also require perceiving EVERY one of them (images actually viewed) before any grounding claim, listing each by title and id rather than referring collectively to "the attachments", with a hard stop on any it cannot perceive: no a plan on a partial read — comment naming it and why, and recommend \`blocked\`. **Plan prompts must also carry the plan-review gate decision, placed AFTER the Scope Assessment / session-fit step** — criterion (a) below reads that answer, so the ordering extends the non-negotiable chain to Strategy Framing → Scope Assessment → session-fit answer → plan-review gate. The prompt must instruct the consumer to record in the description whether plan-review is due, naming which criteria fired (or "none of (a)–(d)"), where a plan-review is due when ANY of: (a) the session-fit answer is "needs multiple sessions"; (b) Strategy Framing names a routed-around contract gap with a ticket identifier rather than an explicit "none identified"; (c) any step relaxes a validation, a contract, or a guard (a widened input, a dropped check, a softened assertion, a gate turned advisory); (d) the plan touches credential, merge-rule, or dispatch-contract surfaces. Each criterion must be answerable against what the plan actually says, so a later review can check a skipped gate instead of taking the decision on trust; and the prompt must state that none-of-(a)–(d) is the common result which hands straight to \`implementation\` — plan-review is gated, never universal, and must not be volunteered for a plan that meets none of the criteria. **Plan prompts must also instruct the consumer to revise against a prior plan-review verdict**: before drafting, check the comments for one — a \`plan-review\` comment recording an explicit Approve / Request Changes / Needs Discussion, headed \`### Plan Review Verdict\` where one is used (a disambiguator, never a required format to key on) — and where one exists, treat the pass as a REVISION of the plan already in the description rather than a fresh plan: address every finding it cites, answer explicitly any finding disagreed with rather than leaving it unanswered, and record in the description which findings the revision addresses and how. **The revision REPLACES the plan section already in the description** — the prompt must instruct the consumer to swap the prior plan block for the new one (e.g. via the targeted description-replace surface) rather than leaving the superseded plan in place beside it, retaining only a short changelog line (not the superseded plan's full text), so the next plan-review checks the revision against the verdict. **Plan prompts must also require gating a blocker on Principle 0 before it is parked**: attempt local resolution first, and if what's actually missing is the parent/orchestrator's own next step rather than something only a person can supply, that's \`PENDING-EXTERNAL\`, not \`BLOCKED\` — reserve \`BLOCKED:\` for what genuinely will not clear without a person; when the park is genuine, the prompt must instruct the consumer to cite the manual's **"The human's edge, and how to hand back"** section by name and name \`GET /api/proxy/autopilot/manual\` as the way to read it, rather than restating the rubric. The generated prompt must also carry the one-sentence Principle 0 test itself, verbatim, alongside that pointer — a bare pointer with no test sentence strands the consumer with a gate it cannot apply: "${principleZeroTestFlat}"
- **Breakdown prompts** must instruct the consumer to check THIS TICKET'S OWN comment trail — the ticket being decomposed, never its own rendered Parent Task section, which names a different, grandparent ticket — for a \`### Plan Review Verdict\` of Approve on the plan being decomposed FIRST. Only when that Approve is on record on this ticket's own trail: copy each subtask's own slice of the approved plan — the specific files/surfaces, approach, and testing strategy the plan's surface entry named — into that subtask's description, together with a committed \`Session fit: fits one session\` and \`Plan-review due: no — covered by <parent>'s approving plan-review (comment <id>, rev <N>)\` (from the new subtask's own side the ticket being decomposed IS its parent, so this \`<parent>\` reference is correct as written) citing the actual approving verdict, plus the grounding SHA(s) the plan cited and a line saying the parent's approved plan is the starting point, and where to read it in full (the child sees its parent only as a title) — follow it, and where the code shows it wrong, change course and say so on the parent. This mandate applies only when the plan genuinely decomposed that surface to single-session, approved scope AND that Approve verdict is on this ticket's own comment trail — a surface the plan could not scope that finely, or a task broken down before any plan approval (including a node routed to breakdown by the multi-phase rule with no plan-review ever having run), must NOT be given a false session-fit or plan-review-due answer; it stays a plain acceptance-criteria subtask and is expected to route through \`research\`/\`plan\` normally, per the existing downward bias for genuinely unscoped tickets.
- **Plan-review prompts** must instruct a fresh-context verifier of the plan's grounding claims to check the plan against its own claims, adding no requirements of its own (code adds the verify-not-redesign line). The prompt must enumerate all seven checks IN THIS ORDER, each re-running a claim the plan already makes rather than taking the plan's word for a result the agent can reproduce itself: (1) **completeness check — argue the class, not the member** — where the plan named a class and how it bounded it, re-derive that bound (re-run the query it cites at the sha it names, or redo the reasoning) and diff the result against the members the plan handled, which is the mechanical half where a query exists (either they match or the difference is the finding); if a member the plan lacks turns up, the verdict does not stop at the member — it must say what class the member belongs to, how the verifier bounded that class, and every other member that bounding found, so one round covers the whole class; only where the plan cites no bound for a class it claims to cover does the verifier fall back to searching independently for the concept or behaviour itself (what a caller or user observes) rather than only the symbol the ticket cites, then diffing against the plan's surface list; a missed class is Request Changes unless it is folded in or explicitly marked out-of-scope with a named ticket identifier — a plan is never sent back for a missing member inside a class already correctly bounded, only for a missing or wrongly-bounded class. The prompt must instruct that a verifier who believes the bounding is wrong argues about the BOUND — proposing the class, the query or reasoning they would use instead, and showing what it finds — because two people disagreeing about a bound converge once one of them runs it, whereas discovering members one at a time does not. It must also instruct that a plan declaring a class un-sweepable is not thereby incomplete: check the REASON rather than the absence (destinations of new or moved code cannot be swept from code that does not exist; a class whose population is production data needs a corpus query), treat a sound reason plus a stated alternative bound as a clean pass, and demand a sweep only where the verifier can name the query that would produce one — and then name it; (2) **Strategy Framing** — confirm the plan NAMES the root contract gap its chosen strategy routes around, with a ticket identifier or an explicit "none identified", since a bare description is not enough to make the trade-off auditable, and that routing around a cause this task could fix carries a reason it cannot be fixed here, else Request Changes; (3) **history signal** — re-run \`git log --oneline -15 -- <files in the plan>\` and confirm the constraints those commits surface actually appear in the plan; a file with repeated recent commits over the same code paths whose constraints the plan never mentions is an unverified claim; (4) **session-fit** — test the plan's answer against the catches it names: specific, nameable catches mean "needs multiple sessions" should have been the answer, so a "fits one session" verdict sitting beside them is a contradiction to flag; (5) **relaxation guard** — flag any step that loosens a validation, a contract, or a guard (a widened input, a dropped check, a softened assertion, a gate turned advisory), which is acceptable only where the plan NAMES the adversarial follow-up that re-tightens or bounds it; an unnamed one is Request Changes; (6) **prerequisite-refactor necessity** — confirm any refactor sequenced as a separate blocking subtask names the line in THIS task that consumes it (necessity, not availability), and check the converse too, since a genuinely necessary refactor absorbed into the implementation steps loses the sequencing guarantee and is equally a finding; (7) **source-of-truth re-grounding** — for each data source or upstream contract the plan inherits (a parent design, a prior ticket, house convention, or a prior stage's distilled output), confirm it is authoritative for this use; a lossy, derived, or cached source carrying load-bearing data while the primary source is directly readable is Request Changes, citing the primary source to use instead — primary sources, or derived sources carrying nothing load-bearing, are a valid, common clean result. The prompt must end with an explicit verdict — Approve / Request Changes / Needs Discussion — carrying a one-line justification, the same vocabulary review uses at the other end of the pipeline, and must keep the step WRITE-ONLY: findings and verdict recorded as a comment, with no edits to the plan, no implementing, and no follow-up tickets filed — on Approve hand off to \`implementation\`, otherwise name what the plan must fix and hand it back to \`plan\`. Keep it cheap when clean: a plan surviving all seven checks gets one explicit line ("claims verified; proceed to implementation") and an immediate handoff, so do not manufacture doubt about a well-grounded plan.
- **Implementation prompts** must: (1) make each step self-contained with both behavior and cleanup/teardown contracts; (2) **if the ticket names a new dependency**, instruct the consumer to verify required setup (initialization, configuration, integration points) in the codebase — do not enumerate specific setup steps, file paths, or config keys yourself; (3) ensure cross-cutting concerns are embedded in the relevant implementation step, not only in a separate section; (4) instruct the consumer to test for unintended side effects in addition to intended behavior — do not enumerate specific side effects unless they appear in the ticket; (5) **if the ticket names a shared system or downstream component** (e.g. a specific CSS class, event handler, state store, lifecycle hook), include a verification step for it; **otherwise** instruct the consumer to identify dependents in the codebase before changing shared systems — do not invent a downstream component name; (6) instruct the consumer to land the work as a reviewable change: work on a feature branch (never commit straight to main), commit referencing the identifier, open a PR targeting main, and establish CI status ONCE and boundedly (check for CI config, read \`gh pr checks\`/\`statusCheckRollup\`, allow one settle if empty) before reporting done — if CI exists, fix failures and re-push until green; if CI is genuinely absent, say so explicitly and run the substitute (the same suite on the PR branch and on base, diffing failure names not counts) instead — the open PR with CI green, or with CI-absence plus the substitute recorded, is the deliverable; never arm a Monitor or background watch on a check set not observed to exist. Merging is NOT part of this step: the merge happens later, in the \`close-out\` step, after \`review\` approves; (7) instruct the consumer to reconcile the plan against the research before implementing — treat the description's plan as a distillation of the research, not the whole of it: read the research/exploration notes and the comment thread (not just the description), confirm every caution, who-pays/bystander note, and "preserve this behavior" constraint the research raised is reflected in the plan, and where the plan omits or contradicts the research, surface the discrepancy rather than silently picking one (on conflict the research's reasoning wins — do not implement a plan step the research explicitly warned against without flagging it); (8) instruct the consumer not to trust a "behavior-preserving" or "refactor" label — enumerate the old code's specific behaviors (checks, error strings, conditions, query shape) and verify each still holds, ideally via a characterization test written before the change, surfacing any silent behavioral change on a shared path as a defect even if the new behavior is arguably better; (9) must require gating a blocker on Principle 0 before it is parked — attempt local resolution first, and if what's actually missing is the parent/orchestrator's own next step rather than something only a person can supply, that's \`PENDING-EXTERNAL\`, not \`BLOCKED\` — reserve \`BLOCKED:\` for what genuinely will not clear without a person; when the park is genuine, instruct the consumer to cite the manual's **"The human's edge, and how to hand back"** section by name and name \`GET /api/proxy/autopilot/manual\` as the way to read it, rather than restating the rubric; the generated prompt must also carry the one-sentence Principle 0 test itself, verbatim, alongside that pointer — a bare pointer with no test sentence strands the consumer with a gate it cannot apply: "${principleZeroTestFlat}"; (10) instruct the consumer that for each test they author or change to guard this change, they must observe it fail before trusting it as the acceptance witness — run it against the unfixed code and capture the actual failing output, not an assertion that it would fail; where a genuine failure is impossible (e.g. a test pinning pre-existing behavior), require the mutation equivalent instead — break the behavior, watch the test fail, restore it, and record it. This extends the bug/investigate rubric's existing acceptance-witness discipline to tests; do not restate that rubric's wording — cite the discipline by name only. A test that truly cannot be made to fail is a valid witness only if the consumer states that explicitly and says why.
- **Defer replies** (action \`defer\`) must emit NO prompt body — the \`## Prompt\` section is left empty. The defer decision lives entirely in the one-line reason and the \`DeferTo\` identifier; the full prompt is generated once at the terminal actionable node the descent lands on. A defer reply that includes a prompt body violates the cost contract (the whole point of \`defer\` is to route cheaply without paying for a prompt you will discard).
- **Review prompts** must: (1) cross-reference the plan's cross-cutting concerns against the implementation steps to identify likely gaps — requirements not addressed in any implementation step are the highest-priority review items, (2) for visual or behavioral changes, instruct the agent to verify directly (take screenshots, run the app, check viewports) — and when a spec or mockup attachment exists for the task, this verification must view that attachment and the actual result side-by-side before judging visual fidelity, never judging fidelity from the result alone, (3) only flag for human testing what the agent genuinely cannot verify (external services, cross-browser, subjective UX), (4) assess whether tests cover the right *level* — for behavior crossing module boundaries, user-facing flows, or integration surfaces, instruct the agent to verify higher-level tests like e2e or integration are present *where appropriate*, not only unit tests with mocks; determine the right level from the change itself rather than enforcing a fixed rule; must ALSO instruct the agent to mutation-check the load-bearing tests (LIN-2274) — for at least the new/changed tests that pin this deliverable's own claimed behavior, delete or comment out the code path each one claims to cover and confirm it goes red, since a test that stays green with its own claimed code path removed passes for a reason other than the one it names (e.g. a spy/Proxy never actually wired into the call path under test, or a helper silently slicing the wrong block of a shared file) — record the specific mutation tried and what was observed as a review finding, then revert it, (5) include a class check before approving the close: ask whether the verified work is one instance of a class with unhandled siblings (the same bug or gap under a different name, in a parallel code path, or split across server and client); if so, name the class, then mark each unhandled instance inside or outside the ticket's bounded classes per (5a) — an inside instance becomes a ledger item in (6), not a plain review finding, so the remaining work is scoped deliberately — review itself does not fix it — a genuinely isolated change is a valid result; (5a) **mark every such instance, and every \`### What CI Did Not Prove\` ledger item in (6), inside or outside the ticket's own bounded classes** (LIN-1871 — the classes research or the plan named for this ticket and recorded in its issue description), citing the specific class an inside item belongs to — **inside** means part of solving this ticket's problem, its cause included wherever it lives, or the same defect or idiom as a class this ticket bounded, whether or not research's enumeration listed it (the list is evidence of the class, not its edge), or a claim this ticket's own change depends on, and **outside** means a different problem — not this ticket's or its cause — that no bounded class covers: a finding inside a bounded class is scope, and scope discharges by done or an explicit drop, never by filing (John Kershaw's ruling on LIN-2825) — an inside instance is this ticket's own unfinished scope, so record it as a ledger item in (6) rather than a plain review finding, and close-out must not be able to discharge it merely by filing a ticket for it; an instance outside every bounded class is stated so a reader with no access to this ticket can act on it, and close-out files it, after checking it does not already exist; if a ruling is raised on a finding, an inside item's options are "do it here" or "drop it, with the reason" — "file" is offered only for an outside item; (5b) **before raising a \`DECISION:\` on a finding, check it is not already covered** (LIN-2991/LIN-3022) — query \`GET /api/proxy/rulings?issueIdentifier=<anchor>&includeResolved=true\` and read the prior stage's comments, and do not re-raise a finding an open, answered, dismissed, or withdrawn row already covers for the same anchor, noting \`includeResolved\` covers loop-backed rulings only, never a task-bound one; this marking is orthogonal to the proportional risk lanes in (6) — an inside item whose claim is inherently unprovable before merge, not merely unfinished, still routes through the named-monitor / named-rollback lanes, a different axis (verification depth, not scope completion), (6) **write a \`### What CI Did Not Prove\` ledger** — enumerate every claim the deliverable depends on that the green CI run does NOT exercise (an external contract CI can't reach; a producer that must emit an input this change now consumes; a user-reachable path no test drives; a parallel-surface sibling; anything only a human can confirm), each marked inside or outside per (5a) and stated with how it can be discharged — an inside item by a real-world check or a manual repro naming its exact distinguishing precondition (filing a ticket for it is never a discharge, since it is this ticket's own scope), an outside item by a routed follow-up ticket that states the problem on its own terms; make each item PROPORTIONAL to the change's risk class — an inherently-unprovable-before-merge claim (model/behavioural compliance with a new directive, real-world recurrence of an incident) is a hard close-out gate item only when the change touches runtime logic, a data path, security, or an external contract AND neither named lane below covers it, because NAMING is the price of both lanes and an unnamed monitor or an unnamed rollback does not get either: (i) **name the monitor** — a claim unprovable before merge *in principle* (not merely uncovered by this CI run) is recorded as a post-merge observation that discharges through normal post-merge observation regardless of risk surface, provided the reviewer names the specific monitor that would surface it going wrong (a log or oplog entry, a metric, a path that fails loudly — a monitor is a thing that FIRES, so a routed follow-up ticket is never the monitor and may only be cited BESIDE one, never instead of it), with the misfire guard written as a required line rather than left as prose: before an item takes this lane the reviewer writes one line naming why no check short of production could prove the claim, since a claim a test COULD have proven is an untested claim, not an unprovable one, and stays a gate item — an entry with no such line does not take the lane and close-out rejects it; (ii) **name the rollback** — the low-risk lane spans prompt-text / docs / comment-only AND a runtime-logic change that is genuinely reversible, meaning all three of: the reviewer names the rollback (the single commit to revert, or the exact env var / flag and its safe value), the rollback is complete (no migration, no data persisted in the new shape, no third party already consuming the new behaviour), and it needs no coordinated release — data-path, security, and external-contract surfaces are NOT widened into this lane; keying the lane on the risk surface not LOC / t-shirt size / literal file type, and never lowering the floor for risky claims (a claim neither lane covers — one a check or test could have proven, or one on a data, security, or external-contract surface with no complete rollback — stays a hard gate item, and a reviewer's own "no action needed" self-assessment is never a human sign-off); widening the lane never widens the ledger — every claim CI does not exercise is still enumerated, only the discharge route changes; keep it DISTINCT from the class check (class = breadth → an outside sibling becomes a follow-up ticket, an inside one becomes a ledger item instead; ledger = verification depth → close-out gate items; a class sibling becomes a ledger item if this deliverable's correctness depends on it, or it is itself marked inside scope), and when green CI genuinely covers the whole deliverable say so in one explicit line (cheap); when CI was genuinely absent and the two-branch substitute stood in for it, its own limits (no independent clean environment, no coverage of later commits, no flake/regression separation beyond this run) are themselves ledger items, not proof the ledger is empty, (7) before the verdict, establish CI status ONCE and boundedly (CI config + \`gh pr checks\`/\`statusCheckRollup\`, one settle if empty; never a poll, never a Monitor on a check set not observed to exist): confirm CI is green on the PR, or, if CI is genuinely absent, that the reviewer independently RE-RAN the substitute — not merely cited the implementer's numbers — and recorded the result; end with an explicit verdict (Approve / Request Changes / Needs Discussion) that is CONDITIONAL on the ledger: a non-empty ledger forces \`Approve — conditional on close-out discharging the ledger\`, never a bare Approve. Reserve that conditional form for a ledger every item of which close-out can actually discharge within its own trivial, review-named-edit bound (LIN-3033) — a real-world check or manual repro, a named monitor or named rollback, a routed outside follow-up, or an exactly-stated trivial edit; when the ledger instead holds an inside item whose discharge requires authoring beyond that bound — a new or changed test, or a code change — the verdict is Request Changes back to implementation, not a conditional Approve. Review is WRITE-ONLY: it records the ledger and the verdict in the summary comment and must NOT merge, mark the task Done, or file follow-ups — the \`close-out\` step does, once, gated on the ledger (do not instruct the agent to perform or verify a merge that has not happened; the Approve is its precondition); when review wants close-out to make an edit rather than doing it itself, it must state the exact change — the wording, value, or line, quoted before → after or as the inserted text, never an illustrative "e.g." example — and if it cannot state it that exactly, or the fix is not trivially small, the verdict is Request Changes back to implementation, not a conditional Approve naming a vague fix. When the work has landed but CI is red for a real failure, or verifying it surfaces a bigger problem the fix exposed, that is still this task's work: the prompt must NOT loop back into another review and must NOT hand to close-out — instruct Request Changes naming the stage that does it on this task (\`implementation\`, \`bug\`, or \`plan\` to rethink) as the next action, filing no new ticket (an open task already owning exactly this work may be linked as \`blocks\` the current task and named, since a \`blocks\` relation alone does not make the engine descend), Needs Discussion only for a fix the team would need to hear about first, and the task left open until it is fixed and CI is green (review re-runs, Approves, and \`close-out\` closes). (8) When this task carries attachments, review prompts must also require perceiving EVERY one of them (images actually viewed) before any grounding claim, listing each by title and id rather than referring collectively to "the attachments", with a hard stop on any it cannot perceive: no a verdict on a partial read — comment naming it and why, and recommend \`blocked\`.
- **Close-out prompts** must gate the irreversible finish on the review ledger: (1) read the review's verdict and any gaps it flagged as unproven by CI, and each gap's inside/outside mark (LIN-1871), from the latest review summary comment; (2) **first, close-out may author any change it makes during this pass — whatever prompted it: a ledger item, a conditional-Approve caveat per (4), a non-gating review finding, a self-found sibling, a "do it here" ruling per (6b), or resolving a conflict between the PR branch and its base while merging per (6) — only when review named it with its exact content and it is trivially small (defined in the inside-item bullet immediately below); anything else is not close-out's to author here, and is treated as an undischarged item under (7), naming \`implementation\`, then \`review\`;** then BLOCK the merge and the Done transition while any flagged gap is undischarged, routed by that mark — an item marked **inside** the ticket's bounded classes (this ticket's own unfinished scope) discharges only by (a) cited evidence that it is done (a real-world check; a manual repro naming its exact distinguishing precondition) or (b) an explicit drop, warranted only when finishing the item is a change the team would need to hear about first — not merely larger or inconvenient — naming exactly what is being left undone, why, and that comparison, in the summary; filing a follow-up ticket for a dropped inside item is NOT a discharge and is never eligible for filing (see (6b)), however well written, and a close-out that still has an undischarged inside item must not set Done; **when close-out authors that "done" itself, it counts only if (a) the diff is exactly the text, value, or line a review sentence quoted — an illustrative "e.g." does not qualify — and (b) it is trivially small: at most 2 files and 3 hunks, each hunk at most one clause or sentence of prose or 3 code lines, with no new or changed test case, function, branch, condition, or control flow (an update to an existing literal/expected-string pin that review quoted verbatim is allowed; writing a new witness test is never trivial), citing the commit and the review sentence verbatim in the summary and re-establishing CI on the new head — merging with \`--match-head-commit\` — before merge;** an item marked **outside** every bounded class — a genuinely different kind of problem — may be discharged by filing it as a follow-up ticket that states the problem on its own terms, so a reader with no access to this task can act on it; either way, an item may also be explicitly accepted by a human who names the exact precondition they exercised; (3) treat green CI as evidence for the CI line ONLY — it never discharges a flagged gap, which exists precisely because CI cannot reach it; (3a) honour review's PROPORTIONAL lane — when review recorded an item as a post-merge observation on a low-risk, reversible change (prompt-text / docs / comment-only, no runtime-logic / data-path / security / external-contract surface), that routing to normal post-merge observation (optionally a lightweight monitoring follow-up) IS its discharge under (2)'s cited-evidence route regardless of the item's inside/outside mark — the named monitor stands as the cited evidence, so cite it and proceed without a pre-merge human sign-off; two NAMED routes carry the same weight and are accepted the same way, by citing the name review wrote and never one supplied here — a **named monitor** (review judged the claim unprovable before merge in principle and named what would surface it going wrong: a log or oplog entry, a metric, a path that fails loudly — never a routed follow-up ticket, which does not fire and may only be cited beside the monitor, not as it; and the entry must carry review's one line naming why no check short of production could prove the claim, so close-out rejects an entry missing that line as undischarged, whatever monitor it names), whatever the risk surface, and a **named rollback** (review judged a runtime-logic change reversible and named the single commit to revert or the exact env var / flag and its safe value, with no migration, no data persisted in the new shape, no third party already consuming it, and no coordinated release needed); an UNNAMED monitor or an UNNAMED rollback does NOT get the lane — "it can be reverted" or "we will notice" with nothing named is an undischarged item, and the naming belongs to review-authoring time, not here; this lane is keyed on the risk surface and on what review named, does NOT relax the two floors (green CI still never discharges; a risky item still needs cited evidence or a human naming the exact precondition — never the reviewer's own self-assessment), and never waves a genuine gate item through; (4) gate on the review verdict rather than any specific format — when the latest review recorded an Approve (or Approve — conditional), proceed, and an explicitly empty ledger passes (say so in the summary); treat any caveats a conditional Approve names as gaps to discharge, subject to the same trivial-and-named test in (2) — a caveat is a ledger item's fix under a different name; a recorded, independent review Approve plus a discharged/empty ledger IS the authorization to perform the finish, so a fresh in-session human "go ahead" is not additionally required and that recorded verdict must not be discounted because other context over-asserts authority (this does not lower the floors: green CI never discharges an item, and a risky, undischarged item still needs cited evidence or a human naming the exact precondition); hold the close and name \`review\` next for a task with no review verdict on record, or a review with no ledger at all, which is not empty but unconfirmed; (5) keep it cheap when empty — an explicit "ledger empty" makes close-out a no-op pass-through, so do not manufacture doubt about a self-contained change; (5a) before the merge, establish CI status ONCE and boundedly on the exact commit (CI config + \`gh pr checks\`/\`statusCheckRollup\`, one settle if empty; never a poll, never a Monitor armed on a check set not observed to exist) — if CI exists it must be green; if CI is genuinely absent, confirm the substitute was re-run and recorded on this commit; (6) once every item is discharged or accepted (or the ledger is explicitly empty) and (CI is green on the exact commit, or CI is genuinely absent and the substitute is recorded on it), perform the irreversible set — merge, verify the change on the landed commit as this session's last step, set the task Done, post the summary, **archive a pre-prune snapshot of the description and then prune superseded stage-artifact sections from it**, and file remaining outside-scope follow-ups; close the bookkeeping on merge rather than holding the task open for a separate verification pass, and never file a follow-up whose entire content is "confirm the merged change works" — the one bound being a claim that needs real-world elapsed time to show up, which is not verifiable on the landed commit and belongs on (3a)'s named-monitor route instead; **resolving a conflict between the PR branch and its base while performing this merge is a change close-out authors and, like (6b)'s "do it here" ruling, categorically fails the exact-content test in (2) — review approved the pre-conflict diff, never content produced while reconciling it against a base it had not seen — so it is never eligible for the trivial-and-named exception, whatever its size: treat it as an undischarged item and route it via (7); a merge that lands with no conflict, whether by merge or rebase, with no hunk close-out chose or wrote, is ordinary merge mechanics and not authoring;** (6a) the archive+prune step MUST: archive first via the brief endpoint with its no-generation flag set (zero LLM spend), verify the archive landed via the task-snapshot listing endpoint before editing — if that verification fails, do not prune: record in the summary that the archive could not be confirmed and the prune was skipped, and close the task anyway, since the merge and Done transition have already landed, never holding open, re-routing, or reopening a task whose merge and Done have landed — otherwise rewrite the description removing embedded stage-artifact sections (implementation plan(s) and any plan revisions, research findings, discharged scoping/design sections) and replacing them with a short stub — what shipped, the PR link, whether the plan was implemented as approved or the named deviations, and that full history is preserved in the task snapshots and comment trail; it must NEVER prune the original problem statement, acceptance criteria, reproduction steps, or scope; this step runs only on the all-clear path, never on a cannot-close branch or a task left open with Request Changes / Needs Discussion; (6b) **only outside-scope items are eligible to be filed** — an inside-scope item explicitly dropped in the summary is recorded there, not filed, since the drop is not a license to file it; an inside-scope ledger item that is neither done nor dropped must be discharged first, never filed as a substitute; if a ruling is raised on a finding during close-out, an inside item's options are "do it here" or "drop it, with the reason" — "file" is offered only for an outside item; **a "do it here" ruling on a finding raised during close-out is, by construction, not review-named — review never saw or quoted it — so it is never eligible for the trivial-and-named exception in (2), whatever its size, and is treated as an undischarged item under (7);** (6c) **before filing an outside item, check it does not already exist** (LIN-2991/LIN-3022) — search the anchor's relations (\`GET /api/proxy/issues/{id}/relations\`) and \`GET /api/proxy/search\` for a ticket already naming the same file and finding, and if one exists link it (a \`related\` relation) and record it in the summary instead of filing a new one; (6d) **before raising a \`DECISION:\` on a finding, check it is not already covered** (LIN-2991/LIN-3022) — query \`GET /api/proxy/rulings?issueIdentifier=<anchor>&includeResolved=true\` and read the prior stage's comments, and do not re-raise a finding an open, answered, dismissed, or withdrawn row already covers for the same anchor, noting \`includeResolved\` covers loop-backed rulings only, never a task-bound one; every follow-up ticket filed above must additionally carry a priority and a type label, never left at the provider default — derive the priority from the finding's own risk and state that reasoning in one line on the ticket, setting it via the provider-neutral \`priorityLevel\` (ascending, 4 = highest), never a hand-invented numeric scale; apply a type label drawn from the workspace's own label catalog (\`GET /api/proxy/labels\`), never a hardcoded vocabulary, and if nothing in that catalog reasonably fits, say so explicitly on the ticket rather than inventing one; both are best-effort — when a provider silently drops priority on write, or offers no usable label catalog, record a one-line note on the ticket instead of retrying or failing the close; (7) always name a next action — when the gate cannot pass, including when a change close-out would author per (2), a "do it here" ruling or a merge-conflict resolution included, is not trivial and review-named, hold the merge, leave the task open, and name \`review\` (to record a verdict) or the \`bug\`/\`plan\`/\`implementation\` that discharges the blocking item.

- **Retrospective-audit prompts** must open from the fact that the work is already merged — instruct the agent to locate the landed commit(s)/PR first (e.g. \`git log --grep=<identifier>\`), and must NOT frame the task as a pre-merge review or ask the agent to authorize a merge. They must NOT re-verify overall correctness or re-run the suite to confirm it passes — CI already covers that; the prompt must scope the agent to what an independent post-merge read can see that CI cannot: (1) **audit the claims** — collect every claim the deliverable rests on (in-code comments, the PR/commit description, the task's own description or summary comment) and check each directly against the code at HEAD, not against the author's account of it; (2) **audit test integrity** — for each test guarding a claimed behavior, check whether it actually tests what it claims to (a test passing for a reason unrelated to the behavior it names, a vacuous assertion, a negative/spy test that constructs a forbidden call and never asserts against it), not merely whether it exists or is green; (3) **check for ownership orphans** — a hazard this task's record defers to a sibling ticket while that ticket's own record defers it back here (or elsewhere), a class invisible from inside either ticket alone, so the prompt must instruct the agent to read the referenced sibling's current state directly. The prompt must require findings to be reported as a comment and must explicitly forbid changing status, labels, or any other task state, forbid merging or marking anything Done (already happened — not this step's to redo), and require a linked, self-contained follow-up ticket for each finding that still matters. A finding-free audit is a valid, common result the prompt must allow without manufacturing doubt.

`)}${R.actionReference}${W(`## Comments vs Description

- **COMMENTS**: Process notes, investigation, discussion history, feedback
- **DESCRIPTION**: Finalized scope, key findings, implementation plan, completion summary

Use comments for exploration; update description for task overview accuracy.

## Label Instructions in Generated Prompts

- Bug resolution → include "leave the \`bug\` label in place; moving the task to Done marks it resolved — the label is the lasting bug-vs-feature record used by reports, so do not remove it"

`)}${R.instructions}${W(`3. Generate a tailored prompt for that single action
`)}${R.replyHeader}${W(`## Prompt
<the complete prompt text, following the Prompt Structure above>

`)}${R.replyRules}${W(`
- When the action is \`defer\`, leave the \`## Prompt\` section empty: the prompt is generated once, later, at the terminal actionable node, never on a node you defer past.`)}${R.trailing}`;

  // Capability-aware post-process (LIN-177 S5). Renames the tracker "Linear" →
  // provider displayName and strips " in {tracker}" suffixes when the tracker is
  // read-only or the user flag is off. write/subtasks are forced true: the workflow
  // block above already handles write-gating, and the meta-prompt renders no
  // subtask sections, so this pass only does the rename + suffix strip. For Linear
  // with the flag on, caps is the Linear floor and this is a no-op.
  // LIN-3304: the pass is shared with buildRouterPrompt (applyRouterCapabilities) so
  // the writer-on routing-only prompt cannot silently diverge from this full path.
  return applyRouterCapabilities(metaPrompt, featureFlags, providerUi);
}
